                    if isinstance(sub, ast.ImportFrom):
                        for a in sub.names:
                            if a.name!='*': names.add(a.asname or a.name)
            elif isinstance(n, ast.Try):
                for sub in ast.walk(n):
                    if isinstance(sub,(ast.Import,)):
                        for a in sub.names: names.add(a.asname or a.name.split('.')[0])
                    if isinstance(sub, ast.ImportFrom):
