                        a=m.args
                        names=[x.arg for x in a.posonlyargs+a.args+a.kwonlyargs]
                        meths[m.name]=(names, a.kwarg is not None, len(a.defaults), len(a.args))
                classes[n.name]=(bases, meths)
            elif isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)):
                a=n.args
                funcs[n.name]=([x.arg for x in a.posonlyargs+a.args+a.kwonlyargs], a.kwarg is not None)

def resolve_method(cls, meth, seen=None):
    seen = seen or set()
    if cls in seen or cls not in classes: return None
    seen.add(cls)
    bases, meths = classes[cls]
    if meth in meths: return meths[meth]
    for b in bases:
        r = resolve_method(b, meth, seen)
        if r: return r
    return None

def accepts_kwargs(cls, meth):
    # any class in MRO whose method has **kwargs
    r = resolve_method(cls, meth)
    return r[1] if r else True

def all_params(cls, meth):
    # union of params along MRO for chained super().__init__(**kwargs)
    out=set(); stack=[cls]; seen=set()
